package cn.adc.appointments;
import cn.adc.duration.DurationPolicyService.Basis;import cn.adc.shared.resource.ResourceLockCoordinator.Version;import org.junit.jupiter.api.Test;import java.time.Instant;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class MiniAvailabilityPlannerTest {
 final Instant start=Instant.parse("2026-12-04T09:00:00Z");
 MiniAvailabilityPlanner.Window window(long dentist,String state){return new MiniAvailabilityPlanner.Window(new Version(dentist,2),81001,dentist,start,start.plusSeconds(3600),state);}
 @Test void arbitraryDateUsesTheSelectedCurrentMinutesInsteadOfThirtyMinuteDefaults(){var slots=MiniAvailabilityPlanner.plan(List.of(window(79001,"EFFECTIVE")),List.of(),new Basis(85001,9,27));assertEquals(2,slots.size());assertEquals(start.plusSeconds(1620),slots.get(0).end());assertTrue(slots.stream().allMatch(MiniAvailabilityPlanner.Slot::available));assertEquals(9,slots.get(0).basis().versionNo());}
 @Test void globalDentistOccupancyBlocksOverlappingSlotsButNotAnotherDentist(){var slots=MiniAvailabilityPlanner.plan(List.of(window(79001,"EFFECTIVE"),window(79002,"EFFECTIVE")),List.of(new MiniAvailabilityPlanner.Occupancy(79001,start,start.plusSeconds(1620))),new Basis(85001,1,27));assertFalse(slots.stream().filter(s->s.dentist()==79001&&s.start().equals(start)).findFirst().orElseThrow().available());assertTrue(slots.stream().filter(s->s.dentist()==79002).allMatch(MiniAvailabilityPlanner.Slot::available));}
 @Test void halfOpenAdjacentAllowedAndOneMicrosecondOverlapUnavailable(){var end=start.plusSeconds(1620);var adjacent=MiniAvailabilityPlanner.plan(List.of(window(79001,"EFFECTIVE")),List.of(new MiniAvailabilityPlanner.Occupancy(79001,start.minusSeconds(60),start)),new Basis(85001,1,27));assertTrue(adjacent.get(0).available());var overlap=MiniAvailabilityPlanner.plan(List.of(window(79001,"EFFECTIVE")),List.of(new MiniAvailabilityPlanner.Occupancy(79001,end.minusNanos(1000),end.plusSeconds(1))),new Basis(85001,1,27));assertFalse(overlap.get(0).available());}
 @Test void draftsAndMissingSourcesNeverBecomeBookable(){assertTrue(MiniAvailabilityPlanner.plan(List.of(window(79001,"DRAFT")),List.of(),new Basis(85001,1,27)).isEmpty());assertThrows(NullPointerException.class,()->MiniAvailabilityPlanner.plan(List.of(window(79001,"EFFECTIVE")),null,new Basis(85001,1,27)));assertThrows(NullPointerException.class,()->MiniAvailabilityPlanner.plan(List.of(window(79001,"EFFECTIVE")),List.of(),null));}
}
